import { useState } from 'react';
import { extractSteamID, normalizeVanityURL } from '../utils/steamUtils';

interface UseSteamSearchResult {
  searchProfile: (input: string) => Promise<string>;
  isLoading: boolean;
  error: string | null;
}

export function useSteamSearch(): UseSteamSearchResult {
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const searchProfile = async (input: string): Promise<string> => {
    setIsLoading(true);
    setError(null);

    try {
      // Intentar extraer SteamID64 de entrada
      const extractedId = extractSteamID(input);
      if (extractedId) {
        return extractedId;
      }

      // Tratar como vanity URL o nombre personalizado
      const normalized = normalizeVanityURL(input);
      const response = await fetch(
        `/api/resolveVanityURL?vanityurl=${encodeURIComponent(normalized)}`
      );
      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.error || 'No se pudo resolver el perfil de Steam');
      }
      const data = await response.json();
      if (!data.steamid) {
        throw new Error('No se pudo encontrar un ID de Steam válido');
      }
      return data.steamid;
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Error al buscar el perfil';
      setError(message);
      throw err;
    } finally {
      setIsLoading(false);
    }
  };

  return { searchProfile, isLoading, error };
}
